function runRow(value=run()):Any{return {scope_id:value.scopeId,probe_id:value.probeId,actor_id:value.actorId,forward_id:value.binding.forwardId,node_id:value.binding.nodeId,binding:JSON.stringify(value.binding),instance_id:value.instanceId,instance_generation:String(value.instanceGeneration),timeout_ms:String(value.timeoutMs),issued_at:String(value.issuedAt),expires_at:String(value.expiresAt),state:value.state,closed_at:value.closedAt,revision:String(value.revision),updated_at:String(value.updatedAt),withdrawn_at:value.withdrawnAt,result_status:null,result_code:null,result_elapsed_ms:null,result_measured_at:null,result_valid_until:null,result_accepted_at:null,result_digest:null,recovery_suspended:0,measurement:'tcp-connect-v1',service_selection:null,result_tls:null,echo_challenge:null,result_echo:null,result_request_bytes:null,result_response_bytes:null};}
function planRow(value=plan()):Any{return {scope_id:value.scopeId,plan_id:value.id,created_by:value.createdBy,created_at:String(value.createdAt),config:JSON.stringify(value.config),config_digest:value.configDigest,origin_binding:JSON.stringify(value.originBinding),forward_id:value.config.forwardId,mode:value.config.mode,expires_at:String(value.config.expiresAt),revision:String(value.revision),state:value.state,decision_count:String(value.decisionCount),accepted_count:String(value.acceptedCount),next_run_at:String(value.nextRunAt),updated_at:String(value.updatedAt),cancelled_by:value.cancelledBy,cancelled_at:value.cancelledAt,last_code:value.lastCode,recovery_suspended:0};}
function sqlFixture(){const calls:{sql:string;args:unknown[]}[]=[],answers:any[]=[],failure=new Error('native transaction');const tx={async execute(sql:string,args:unknown[]=[]){calls.push({sql,args});const answer=answers.shift();if(answer instanceof Error)throw answer;return [answer??{affectedRows:1},[]];},async query(sql:string){calls.push({sql,args:[]});const answer=answers.shift();if(answer instanceof Error)throw answer;return [answer??[],[]];}} as unknown as Transaction;return {tx,calls,answers,failure};}

