 for(const [Owner,names]of [[MySqlProbeRuns,['lockScope','losses','missingUpdate','insert','get','put','history']],[MySqlProbePlans,['lockScope','losses','create','get','put','append','decisions','history','due','defer','isolate']]]as const){assert.equal(Owner.length,0);for(const name of names){const descriptor=Object.getOwnPropertyDescriptor(Owner.prototype,name)!;assert.equal(descriptor.enumerable,false);assert.equal(descriptor.value.constructor.name,'AsyncFunction');}}
