const databaseURL=process.env.TUNEX_TEST_DATABASE_URL;
async function database(action:(db:MySqlUnitOfWork)=>Promise<void>){
 const admin=await createConnection(databaseURL!),name='tunex_history_plans_'+randomUUID().replaceAll('-',''),url=new URL(databaseURL!);url.pathname='/'+name;const db=new MySqlUnitOfWork(url.toString());let created=false;
 try{await admin.query(`CREATE DATABASE \`${name}\``);created=true;await db.migrate();await db.transaction(async tx=>{await write(tx,'INSERT INTO accounts(id,token_hash) VALUES(?,?)',['actor','a'.repeat(64)]);await write(tx,'INSERT INTO scopes(id,owner_id) VALUES(?,?)',['scope-a','actor']);await write(tx,'INSERT INTO scope_members(scope_id,actor_id,can_manage) VALUES(?,?,TRUE)',['scope-a','actor']);await write(tx,'INSERT INTO accounts(id,token_hash) VALUES(?,?)',['other-manager','b'.repeat(64)]);await write(tx,'INSERT INTO scope_members(scope_id,actor_id,can_manage) VALUES(?,?,TRUE)',['scope-a','other-manager']);});await action(db);}
 finally{try{await db.close();if(created)await admin.query(`DROP DATABASE \`${name}\``);}finally{await admin.end();}}
}
async function snapshot(db:MySqlUnitOfWork){const tables=await rows<{name:string}>(db.pool,'SELECT TABLE_NAME name FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY TABLE_NAME');const out:Any={};for(const {name}of tables)out[name]=(await rows(db.pool,`SELECT * FROM \`${name}\``)).map(v=>JSON.stringify(v)).sort();return out;}
function instrument(tx:Transaction,after:(sql:string,args:unknown[])=>void):Transaction{return new Proxy(tx,{get(target,key){if(key==='execute')return async(sql:string,args:unknown[]=[])=>{const out=await target.execute(sql,args);if(/^(INSERT|UPDATE|DELETE)\b/.test(sql.trim()))after(sql,args);return out;};const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;}});}
async function everyWrite(db:MySqlUnitOfWork,label:string,action:(tx:Transaction)=>Promise<unknown>,required:string[]){
 const before=await snapshot(db),stop=new Error('rollback complete '+label),fault=new Error('after native write '+label),sql:string[]=[];
 await assert.rejects(db.transaction(async tx=>{await action(instrument(tx,s=>sql.push(s)));throw stop;}),error=>error===stop);assert.ok(sql.length>0,label);for(const fragment of required)assert.ok(sql.some(s=>s.includes(fragment)),label+': '+fragment);assert.deepEqual(await snapshot(db),before);
 for(let position=1;position<=sql.length;position++){let writes=0;await assert.rejects(db.transaction(tx=>action(instrument(tx,()=>{if(++writes===position)throw fault;}))),error=>error===fault);assert.equal(writes,position,label+' write '+position);assert.deepEqual(await snapshot(db),before,label+' rollback '+position);}
 return sql;
}
function authority(value=run()):ProbePermitRecord{return {id:value.probeId,actorId:value.actorId,scopeId:value.scopeId,binding:value.binding,instanceId:value.instanceId,instanceGeneration:value.instanceGeneration,fingerprint:'c'.repeat(64),timeoutMs:value.timeoutMs,issuedAt:value.issuedAt,expiresAt:value.expiresAt,state:value.state,closedAt:value.closedAt};}
// The recorder accepts the original permit summary, not storage revision/result metadata.
function historyPermit(value:ProbeRunRecord):ProbeRunPermit{return {probeId:value.probeId,actorId:value.actorId,scopeId:value.scopeId,binding:value.binding,instanceId:value.instanceId,instanceGeneration:value.instanceGeneration,timeoutMs:value.timeoutMs,issuedAt:value.issuedAt,expiresAt:value.expiresAt,state:value.state,closedAt:value.closedAt,...(value.measurement===undefined?{}:{measurement:value.measurement}),...(value.service===undefined?{}:{service:value.service}),...(value.echoChallenge===undefined?{}:{echoChallenge:value.echoChallenge})};}
function integrated(db:MySqlUnitOfWork,tx:Transaction,options:{refusal?:Error;schedule?:boolean}={}){
 const history=new MySqlProbeHistoryStore(probeRunStorageValues),recorder=new ProbeRunHistoryRecorder(history),permits=new MySqlProbePermits(),identity=new Identity(db),store=new MySqlProbePlanStore(probePlanStorageValues);let issued=0;
 const issuer:ProbePlanIssuer<Transaction>={async previewIn(actual,actor,scope,config){assert.equal(actual,tx);assert.deepEqual([actor,scope],['actor','scope-a']);return {version:1,executable:false,dispatch:'not-implemented',independentProbe:false,health:'unknown',scopeId:scope,binding:copy(wire.binding),timeoutMs:config.timeoutMs,maxAttempts:1,applicationPayloadBytes:0,plannedAt:new Date(at).toISOString(),expiresAt:new Date(at+2000).toISOString(),kind:'tcp-connect',point:'agent-direct-egress'};},async issueIn(actual,actor,scope,config){assert.equal(actual,tx);assert.deepEqual([actor,scope],['actor','scope-a']);const value={...run('issued-'+(++issued)),issuedAt:at,updatedAt:at,expiresAt:at+2000};await permits.insert(actual,authority(value));const [mutated]=await rows<{state:string}>(actual,'SELECT state FROM probe_permits WHERE id=?',[value.probeId]);assert.equal(mutated!.state,'issued');await recorder.recordIn(actual,{kind:'issued',permit:historyPermit(value),at,result:null});if(options.refusal)throw options.refusal;return {status:202,body:{probeId:value.probeId,forwardId:config.forwardId,issuedAt:new Date(at).toISOString(),expiresAt:new Date(at+2000).toISOString(),dispatch:'agent-poll',executionEnabled:false}};}};
 const boundary={async transaction<T>(action:(actual:Transaction)=>Promise<T>){return action(tx);}};return new ProbePlans({db:boundary,auth:identity,access:new ResourceAccess(identity,new MySqlResourceAccessStore()),requests:new Idempotency(),store,issuer,executionEnabled:true,scheduleEnabled:options.schedule??false,clock:()=>at,clockSkewMs:50});
}

