 await assert.rejects(runOwner().get('other-manager','scope-a','private-run'),{code:'NOT_FOUND'});
 await assert.rejects(planOwner().get('other-manager','scope-a','private-plan'),{code:'NOT_FOUND'});
 const governedRuns=await runOwner().history('actor','scope-a'),governedPlans=await planOwner().history('actor','scope-a');
 assert.equal(governedRuns.items.length,2);assert.notEqual(governedRuns.losses,null);assert.equal(governedPlans.items.length,2);assert.notEqual(governedPlans.losses,null);
